const $=id=>document.getElementById(id),historyDown=[],historyUp=[],deviceHistory=new Map(),target={cpu:0,ram:0,down:0,up:0,temp:0,ping:0},shown={cpu:0,ram:0,down:0,up:0,temp:0,ping:0};let hasTarget=false,lastFrame=performance.now(),lastChartSample=0,tempAvailable=false,pingAvailable=false;
const bytes=value=>{const units=['B','KB','MB','GB','TB'];let size=Math.max(0,+value||0),i=0;while(size>=1024&&i<4){size/=1024;i++}return size.toFixed(i>1?1:0)+' '+units[i]},rate=value=>((+value||0)*8/1e6).toFixed(2)+' Mb/s',duration=s=>{s=Math.max(0,+s||0);const d=Math.floor(s/86400),h=Math.floor(s%86400/3600),m=Math.floor(s%3600/60);return(d?d+'g ':'')+h+'h '+m+'m'},esc=v=>String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function draw(){const c=$('chart'),r=c.getBoundingClientRect(),q=devicePixelRatio||1;c.width=r.width*q;c.height=r.height*q;const x=c.getContext('2d'),sets=[[historyDown,'#55d7ff'],[historyUp,'#ef4056']],max=Math.max(1,...historyDown,...historyUp);x.lineWidth=2.5*q;x.lineJoin='round';sets.forEach(([v,color])=>{if(v.length<2)return;x.beginPath();v.forEach((n,i)=>{const px=i/59*c.width,py=c.height-n/max*c.height*.78-c.height*.1;i?x.lineTo(px,py):x.moveTo(px,py)});x.strokeStyle=color;x.shadowColor=color;x.shadowBlur=9*q;x.stroke();x.shadowBlur=0})}
function miniChart(values){const max=Math.max(1,...values),points=values.map((n,i)=>`${values.length<2?0:i/(values.length-1)*120},${37-n/max*31}`).join(' ');return `<svg class="spark" viewBox="0 0 124 39" preserveAspectRatio="none"><polyline points="${points}" fill="none" stroke="#55d7ff" stroke-width="2.3" vector-effect="non-scaling-stroke"/></svg>`}
