function renderAssist(a){a=a||{};const online=!!a.online,bar=$('assistBar'),gpu=a.gpuStats||{},profiles=a.profiles||{};bar.classList.toggle('offline',!online);$('assistState').textContent=online?((+a.activeStreams||0)?'ATTIVO · il fisso sta alleggerendo il server':'ONLINE · pronto a intervenire'):(a.enabled?'SPENTO O NON RAGGIUNGIBILE':'ASSISTENZA DISATTIVATA');$('assistGpu').textContent=online&&gpu.utilization!=null?Math.round(gpu.utilization)+'%':'--%';$('assistEncoder').textContent=online&&gpu.encoderUtilization!=null?Math.round(gpu.encoderUtilization)+'%':'--%';$('assistStreams').textContent=online?(a.activeStreams||0):0;$('assistViewers').textContent=online?(a.viewers||0):0;$('assistRate').textContent=online?(+a.outputMbps||0).toFixed(2)+' Mb/s':'0 Mb/s';$('assistSaved').textContent=online?(a.providerConnectionsSaved||0):0;$('assistProfiles').textContent=online?((profiles.sd||0)+(profiles.hd||0)+(profiles.fullhd||0)):0}
