function renderLoadTest(t,p,n,s,r){t=t||{};p=p||{};n=n||{};s=s||{};r=r||{};const viewers=(t.viewers||[]).filter(v=>/test spettatore|loadtest|simulat/i.test(String(v.device||v.deviceType||''))),count=viewers.length,bar=$('loadTestBar'),ram=s.memoryTotal?(+s.memoryUsed||0)/(+s.memoryTotal||1)*100:0;bar.classList.toggle('idle',count===0);$('loadTestState').textContent=count?`TEST ATTIVO · ${count} FLUSSI SIMULTANEI`:'NESSUN TEST ATTIVO';$('loadTestViewers').textContent=count;$('loadTestTarget').textContent=(+p.targetDelaySeconds||0)+' s';$('loadTestReady').textContent=(+p.readySeconds||0).toFixed(1)+' s';$('loadTestDown').textContent=((+n.downloadBps||0)*8/1000000).toFixed(1)+' Mbps';$('loadTestCpu').textContent=(+s.cpuPercent||0).toFixed(0)+'%';$('loadTestRam').textContent=ram.toFixed(0)+'%';$('loadTestErrors').textContent=r.providerErrorsFiveMinutes||0}
function renderViewers(items){if(!items.length){$('viewers').innerHTML='<div class="empty"><div><i>TV</i><strong>Nessuna riproduzione attiva</strong><p>Quando un dispositivo avvia un canale comparirà qui.</p></div></div>';return}$('viewers').innerHTML=items.map(v=>{const key=v.id||v.device,h=deviceHistory.get(key)||[];h.push(+v.bandwidthBps||0);if(h.length>30)h.shift();deviceHistory.set(key,h);const labels={good:'STABILE',warning:'ATTENZIONE',critical:'BUFFERING',recent:'RECENTE'},icon=/mobile|iphone|android|ipad/i.test(v.deviceType||v.device)?'MOB':'PC';return `<div class="viewer"><div class="avatar">${icon}</div><div class="viewer-name"><strong>${esc(v.device)}</strong><span>${esc(v.channel)} · ${esc(v.group)} · ${esc(v.deviceType)}</span></div><div class="health ${esc(v.health)}">${labels[v.health]||'ONLINE'}</div><div class="viewer-stats"><div class="viewer-stat"><small>Ping device</small><b>${v.rttMs?Math.round(v.rttMs)+' ms':'misuro…'}</b></div><div class="viewer-stat"><small>Buffer</small><b>${(+v.bufferSeconds||0).toFixed(1)} s</b></div><div class="viewer-stat"><small>Banda video</small><b>${rate(v.bandwidthBps)}</b></div><div class="viewer-stat"><small>Cache segmenti</small><b>${v.cachePercent||0}%</b></div><div class="viewer-stat"><small>Frame persi</small><b>${(+v.droppedPercent||0).toFixed(2)}%</b></div>${miniChart(h)}</div></div>`}).join('')}
async function refresh(){try{const response=await fetch('/api/dashboard-stats.php?ts='+Date.now(),{cache:'no-store'}),data=await response.json();if(!response.ok||!data.ok)throw 0;const s=data.server,n=data.network,t=data.streaming,r=data.requests||{},c=data.catalog||{},runtime=data.runtime||{},ram=s.memoryTotal?s.memoryUsed/s.memoryTotal*100:0,diskPct=s.diskTotal?s.diskUsed/s.diskTotal*100:0;target.cpu=+s.cpuPercent||0;target.ram=ram;target.down=+n.downloadBps||0;target.up=+n.uploadBps||0;tempAvailable=s.temperature!=null;pingAvailable=s.pingMs!=null;if(tempAvailable)target.temp=+s.temperature||0;if(pingAvailable)target.ping=+s.pingMs||0;if(!hasTarget){Object.assign(shown,target);hasTarget=true}$('status').textContent='SERVER ONLINE';$('load').textContent='carico '+s.load[0];$('ramDetail').textContent=bytes(s.memoryUsed)+' / '+bytes(s.memoryTotal);$('disk').textContent=diskPct.toFixed(0)+'%';$('diskDetail').textContent=bytes(s.diskTotal-s.diskUsed)+' liberi';$('active').textContent=t.activeViewers;$('sessions').textContent=t.sessions+' sessioni autorizzate';$('requests').textContent=(r.providerCallsMinute||0)+'/min';$('requestDetail').textContent=(r.segmentsMinute||0)+' segmenti · '+(r.adaptiveMinute||0)+' RTX · '+(r.relayMinute||0)+' relay';$('segmentLatency').textContent=r.providerAvgMs?Math.round(r.providerAvgMs)+' ms':'N/D';$('providerDetail').textContent=(r.providerHost||'Provider configurato')+' · HTTP '+(r.lastProviderStatus||'--');$('streamErrors').textContent=r.providerErrorsFiveMinutes||0;$('streamErrorDetail').textContent=(r.abortedFiveMinutes||0)+' interrotte · ultimi 5 minuti';$('workers').textContent=(runtime.busyWorkers||0)+' / '+(runtime.workers||0);$('workerDetail').textContent=(runtime.mediaWorkers||0)+' video · '+(runtime.idleWorkers||0)+' liberi';$('catalogChannels').textContent=(c.channels||0).toLocaleString('it-IT');$('catalogDetail').textContent=(c.groups||0)+' categorie · '+(c.cached?'cache attiva':'cache aggiornata')+' · '+(c.loadMs||0)+' ms';$('uptime').textContent='Uptime '+duration(s.uptime);$('updated').textContent='Aggiornato ora';renderWorkers(runtime);renderLoadTest(t,data.prefetch,n,s,r);renderPrefetch(data.prefetch);renderAssist(data.desktopAssist);renderViewers(t.viewers||[])}catch(e){$('status').textContent='CONNESSIONE PERSA';$('updated').textContent='Riconnessione…'}}
let dashboardRefreshBusy=false;const refreshDashboardOnce=refresh;refresh=async function(){if(dashboardRefreshBusy)return;dashboardRefreshBusy=true;try{await refreshDashboardOnce()}finally{dashboardRefreshBusy=false}};
function animate(){const now=performance.now(),dt=Math.min(200,now-lastFrame),blend=1-Math.exp(-dt/650);lastFrame=now;if(hasTarget){Object.keys(shown).forEach(k=>shown[k]+=(target[k]-shown[k])*blend);$('cpu').textContent=shown.cpu.toFixed(0)+'%';$('ram').textContent=shown.ram.toFixed(0)+'%';$('down').textContent=rate(shown.down);$('up').textContent=rate(shown.up);$('streamRate').textContent=rate(shown.up);$('temp').textContent=tempAvailable?shown.temp.toFixed(0)+'°':'N/D';$('ping').textContent=pingAvailable?shown.ping.toFixed(0)+' ms':'N/D';if(now-lastChartSample>=1000){historyDown.push(shown.down);historyUp.push(shown.up);if(historyDown.length>60)historyDown.shift();if(historyUp.length>60)historyUp.shift();lastChartSample=now;draw()}}}
function tick(){const n=new Date;$('clock').textContent=n.toLocaleTimeString('it-IT');$('date').textContent=n.toLocaleDateString('it-IT',{weekday:'long',day:'numeric',month:'long'})}tick();refresh();animate();setInterval(animate,500);setInterval(tick,1000);setInterval(refresh,4000);addEventListener('resize',draw);
</script></body></html>
